mapper.select:
SELECT pledge_id, store_id, merchant_member_id, coupon_id, supply_ref, quantity, service_start, service_end,
       redeem_start, redeem_end, terms, minor_restricted, state, created_at
FROM w17_reward_pledge WHERE pledge_id=#{pledgeId}

mapper.update:
UPDATE w17_reward_pledge
SET quantity=#{quantity}, service_start=#{serviceStart}, service_end=#{serviceEnd},
    redeem_start=#{redeemStart}, redeem_end=#{redeemEnd}, terms=#{terms}, minor_restricted=#{minorRestricted}
WHERE pledge_id=#{pledgeId}

UPDATE w17_reward_pledge_version
SET state='CONFIRMED', merchant_member_id=#{memberId}, merchant_hash=#{hash}, merchant_confirmed_at=#{at}
WHERE version_id=#{versionId} AND state='SUBMITTED'

UPDATE w17_reward_pledge_version
SET state='FROZEN', reviewer_member_id=#{memberId}, reviewer_hash=#{hash}, rule_version=#{ruleVersion}, frozen_at=#{at}
WHERE version_id=#{versionId} AND state='CONFIRMED' AND merchant_member_id IS NOT NULL AND merchant_member_id <> #{memberId}

mapper.select:
SELECT award_id, version_id, rule_version, beneficiary_id, reward_scope, fact_ref, history_id, state, request_id, created_at
FROM w17_reward_award
WHERE rule_version=#{ruleVersion} AND beneficiary_id=#{beneficiaryId} AND reward_scope=#{rewardScope} AND fact_ref=#{factRef}
